// Algoritmo de Gauss para Domingo de Pascua + Ley Emiliani (Colombia).
function easter(year) {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const month = Math.floor((h + l - 7 * m + 114) / 31);
  const day = ((h + l - 7 * m + 114) % 31) + 1;
  return new Date(Date.UTC(year, month - 1, day));
}
function addDays(d, n) { return new Date(d.getTime() + n * 86400000); }
function toMonday(d) {
  const dow = d.getUTCDay();
  const offset = (1 - dow + 7) % 7;
  return addDays(d, offset);
}
function fmt(d) { return d.toISOString().split('T')[0]; }

// target_year: año siguiente al actual en TZ Bogotá
const todayBog = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
const currentYear = parseInt(todayBog.split('-')[0], 10);
const year = currentYear + 1;

const e = easter(year);
const lista = [
  // Fechas FIJAS (no se mueven)
  { fecha: `${year}-01-01`, nombre: 'Año Nuevo' },
  { fecha: `${year}-05-01`, nombre: 'Día del Trabajo' },
  { fecha: `${year}-07-20`, nombre: 'Día de la Independencia' },
  { fecha: `${year}-08-07`, nombre: 'Batalla de Boyacá' },
  { fecha: `${year}-12-08`, nombre: 'Inmaculada Concepción' },
  { fecha: `${year}-12-25`, nombre: 'Navidad' },
  // Ley Emiliani — trasladados al lunes siguiente si no caen en lunes
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 0, 6)))),  nombre: 'Reyes Magos' },
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 2, 19)))), nombre: 'San José' },
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 5, 29)))), nombre: 'San Pedro y San Pablo' },
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 7, 15)))), nombre: 'Asunción de la Virgen' },
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 9, 12)))), nombre: 'Día de la Raza' },
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 10, 1)))), nombre: 'Todos los Santos' },
  { fecha: fmt(toMonday(new Date(Date.UTC(year, 10, 11)))),nombre: 'Independencia de Cartagena' },
  // Semana Santa y postpascuales
  { fecha: fmt(addDays(e, -3)), nombre: 'Jueves Santo' },
  { fecha: fmt(addDays(e, -2)), nombre: 'Viernes Santo' },
  { fecha: fmt(addDays(e, 43)), nombre: 'Ascensión del Señor' },
  { fecha: fmt(addDays(e, 64)), nombre: 'Corpus Christi' },
  { fecha: fmt(addDays(e, 71)), nombre: 'Sagrado Corazón' },
];

return [{ json: { target_year: year, festivos: lista, festivos_json: JSON.stringify(lista) } }];

